import { MONTH_NAMES, MONTH_NAMES_SHORT } from "./types.js";
export const parseDate = (date) => {
    if (!date)
        return null;
    if (typeof date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(date))
        return parseInputDate(date, 'YYYY-MM-DD');
    const result = new Date(date);
    if (isNaN(result.getTime()))
        return null;
    result.setHours(0, 0, 0, 0);
    return result;
};
export const parseInputDate = (text, format) => {
    const tokens = [];
    const escape = (value) => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const pattern = format.split(/(YYYY|MMMM|MMM|YY|MM|DD|M|D)/).map(part => {
        if (!/^(YYYY|MMMM|MMM|YY|MM|DD|M|D)$/.test(part))
            return escape(part);
        tokens.push(part);
        if (part === 'MMMM')
            return '(' + MONTH_NAMES.join('|') + ')';
        if (part === 'MMM')
            return '(' + MONTH_NAMES_SHORT.join('|') + ')';
        return part === 'YYYY' ? '(\\d{4})' : part === 'YY' ? '(\\d{2})' : '(\\d{1,2})';
    }).join('');
    const match = new RegExp('^' + pattern + '$', 'i').exec(text.trim());
    if (!match)
        return null;
    let year = 0, month = 0, day = 0;
    tokens.forEach((token, index) => {
        const value = match[index + 1];
        if (token === 'YYYY')
            year = Number(value);
        else if (token === 'YY')
            year = 2000 + Number(value);
        else if (token === 'MMMM' || token === 'MMM')
            month = (token === 'MMMM' ? MONTH_NAMES : MONTH_NAMES_SHORT).findIndex(name => name.toLowerCase() === value.toLowerCase()) + 1;
        else if (token.startsWith('M'))
            month = Number(value);
        else
            day = Number(value);
    });
    const result = new Date(0);
    result.setFullYear(year, month - 1, day);
    result.setHours(0, 0, 0, 0);
    return year >= 1 && result.getFullYear() === year && result.getMonth() === month - 1 && result.getDate() === day ? result : null;
};
export const formatDate = (date, format = 'MM/DD/YYYY') => {
    if (!date || !(date instanceof Date) || isNaN(date.getTime())) {
        return '';
    }
    let result = '';
    let i = 0;
    while (i < format.length) {
        if (format.substring(i, i + 4) === 'MMMM') {
            result += MONTH_NAMES[date.getMonth()];
            i += 4;
        }
        else if (format.substring(i, i + 3) === 'MMM') {
            result += MONTH_NAMES_SHORT[date.getMonth()];
            i += 3;
        }
        else if (format.substring(i, i + 2) === 'MM') {
            result += (date.getMonth() + 1).toString().padStart(2, '0');
            i += 2;
        }
        else if (format.substring(i, i + 1) === 'M') {
            result += (date.getMonth() + 1);
            i += 1;
        }
        else if (format.substring(i, i + 4) === 'YYYY') {
            result += date.getFullYear();
            i += 4;
        }
        else if (format.substring(i, i + 2) === 'YY') {
            result += date.getFullYear().toString().slice(-2);
            i += 2;
        }
        else if (format.substring(i, i + 2) === 'DD') {
            result += date.getDate().toString().padStart(2, '0');
            i += 2;
        }
        else if (format.substring(i, i + 1) === 'D') {
            result += date.getDate();
            i += 1;
        }
        else {
            result += format[i];
            i += 1;
        }
    }
    return result;
};
export const getDaysInMonth = (year, month) => {
    return new Date(year, month + 1, 0).getDate();
};
export const getFirstDayOfMonth = (year, month) => {
    return new Date(year, month, 1).getDay();
};
export const isSameDay = (date1, date2) => {
    return (date1.getDate() === date2.getDate() &&
        date1.getMonth() === date2.getMonth() &&
        date1.getFullYear() === date2.getFullYear());
};
export const isDateInRange = (date, startDate, endDate) => {
    const timestamp = date.getTime();
    return timestamp >= startDate.getTime() && timestamp <= endDate.getTime();
};
export const generateCalendarDates = (year, month, selectedDate = null, rangeEndDate = null, minDate = null, maxDate = null) => {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const outOfRange = (date) => Boolean((minDate && date < minDate) || (maxDate && date > maxDate));
    const result = [];
    const firstDay = getFirstDayOfMonth(year, month);
    const daysInPrevMonth = getDaysInMonth(year, month - 1);
    for (let i = firstDay - 1; i >= 0; i--) {
        const date = new Date(year, month - 1, daysInPrevMonth - i);
        const isDisabled = outOfRange(date);
        result.push({
            date,
            day: date.getDate(),
            isCurrentMonth: false,
            isToday: isSameDay(date, today),
            isSelected: selectedDate ? isSameDay(date, selectedDate) : false,
            isDisabled
        });
    }
    const daysInMonth = getDaysInMonth(year, month);
    for (let i = 1; i <= daysInMonth; i++) {
        const date = new Date(year, month, i);
        const isSelected = selectedDate ? isSameDay(date, selectedDate) : false;
        const isDisabled = outOfRange(date);
        const calendarDate = {
            date,
            day: i,
            isCurrentMonth: true,
            isToday: isSameDay(date, today),
            isSelected,
            isDisabled
        };
        if (selectedDate && rangeEndDate) {
            calendarDate.isRangeStart = isSameDay(date, selectedDate);
            calendarDate.isRangeEnd = isSameDay(date, rangeEndDate);
            calendarDate.isRangeMiddle = isDateInRange(date, selectedDate, rangeEndDate) &&
                !calendarDate.isRangeStart && !calendarDate.isRangeEnd;
        }
        result.push(calendarDate);
    }
    const totalDaysNeeded = 42;
    const remainingDays = totalDaysNeeded - result.length;
    for (let i = 1; i <= remainingDays; i++) {
        const date = new Date(year, month + 1, i);
        const isDisabled = outOfRange(date);
        result.push({
            date,
            day: i,
            isCurrentMonth: false,
            isToday: isSameDay(date, today),
            isSelected: selectedDate ? isSameDay(date, selectedDate) : false,
            isDisabled
        });
    }
    return result;
};
export const addDays = (date, days) => {
    const result = new Date(date);
    result.setDate(result.getDate() + days);
    return result;
};
export const addMonths = (date, months) => {
    const result = new Date(date);
    const day = result.getDate();
    result.setDate(1);
    result.setMonth(result.getMonth() + months);
    result.setDate(Math.min(day, getDaysInMonth(result.getFullYear(), result.getMonth())));
    return result;
};
export const addYears = (date, years) => {
    return addMonths(date, years * 12);
};
const isoDate = (date) => (date ? formatDate(date, "YYYY-MM-DD") : "");
export const toIsoValue = (value, end) => Array.isArray(value) ? `${isoDate(value[0])}/${isoDate(value[1])}` : value && end ? `${isoDate(value)}/${isoDate(end)}` : isoDate(value);
